PROGRAM ST520_HARDUGN
VAR
    trigReset   : R_TRIG;
    cntDetalj   : CTUD;
    tmrKvar     : TON;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDrift      : BOOL := FALSE;
    xTempOk     : BOOL := FALSE;
    xStilla     : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. Den har logiken ror inte
   sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

(* Rakningen: en detalj upp per stigande flank pa fotocellen in, en ned per
   stigande flank pa fotocellen ut. Raknaren nollstalls ALDRIG av logiken -
   detaljerna ligger kvar i ugnen aven nar nagon kvitterar ett larm, och en
   raknare som nollstalls pa kvittensen sager att ugnen ar tom nar den inte ar
   det. *)
cntDetalj(CU := ST520_PEC_IN, CD := ST520_PEC_OUT, R := FALSE, LD := FALSE,
          PV := 99);
ST520_PRT_CNT := cntDetalj.CV;

(* --- larmkallorna samlas fore domen, sa SYS_ALARM aldrig slapar ett scan
       efter de don den ska stoppa. --- *)

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Overtemperatur ar alltid ett larm: over 195,0 grader C brinner lacken
   oavsett om det ligger nagot i ugnen. *)
IF ST520_OVN_TMP > 195.0 THEN
    xLarm := TRUE;
END_IF;

(* Undertemperatur ar ett larm bara med gods i ugnen. Fran kall ugn ligger
   zonen under 175,0 grader C i tiotals minuter, och inmatningsstoppet
   slapper anda inte in nagon detalj dit. *)
IF ST520_PRT_CNT > 0 AND ST520_OVN_TMP < 175.0 THEN
    xLarm := TRUE;
END_IF;

(* Stillestandsvakt. Star kedjan still med detaljer i ugnen ligger de kvar i
   varmen och maste ut. Vakten laser kedjelaget fran forra scan; 20 ms spelar
   ingen roll for en vakt pa 5,0 s. *)
xStilla := (ST520_PRT_CNT > 0) AND NOT ST520_CNV_RUN;
tmrKvar(IN := xStilla, PT := T#5s);
IF tmrKvar.Q THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET och ett aterstallt
   nodstopp. Larmet slapper aldrig av sig sjalvt. *)
IF trigReset.Q AND EMG_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDrift := EMG_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;
xTempOk := ST520_OVN_TMP >= 175.0 AND ST520_OVN_TMP <= 195.0;

(* Kedjan halls pa 0,010 m/s av frekvensomriktaren; styrningen kommenderar
   bara gang, och uppehallstiden foljer av ugnens langd. *)
ST520_CNV_RUN := xDrift;

(* Ingen detalj slapps in forran zonen ar inne i hardschemats fonster. *)
ST520_STP_IN_OPEN := xDrift AND xTempOk;

(* Varmen far ga aven utan kvittens och utan automatlage - annars blir ugnen
   aldrig varm - men aldrig med brutet nodstopp, aldrig pa larm och aldrig
   nar kedjan star still med detaljer i ugnen. *)
ST520_OVN_HEAT := EMG_OK AND NOT xLarm AND (ST520_OVN_TMP < 180.0)
                  AND (ST520_CNV_RUN OR ST520_PRT_CNT = 0);
END_PROGRAM

